# config.py - RetroDB Configuration
# ================================================
# Application constants and internal defaults.
# DO NOT edit this file — all user settings (paths, API keys) are configured
# via the web UI and stored in data/settings.json and data/scraper_settings.json.
#
# SETUP: Copy this file to config.py, then run the app and use the setup wizard.
#   cp config.example.py config.py
#
# Environment variable overrides (RETRODB_ prefix):
#   RETRODB_DB_PATH       - Database file path
#   RETRODB_HOST          - Server bind address (default: 0.0.0.0)
#   RETRODB_PORT          - Server port (default: 5000)
#   RETRODB_DEBUG         - Debug mode: "true" or "false" (default: false)
#   RETRODB_SECRET_KEY    - Flask secret key (overrides auto-generated key)

import os
import sys

# =============================================================================
# INTERNAL PATHS (not user-configurable here — use Settings page)
# =============================================================================

# BASE_DIR  — writable user data root (database, logs, scraped media, settings).
# BUNDLE_DIR — read-only app assets root (templates, CSS/JS/fonts, vendored docs).
#
# In a normal `python app.py` install they are the same directory.  In a
# PyInstaller frozen bundle (Pass 46.3) BASE_DIR sits next to the launcher
# while BUNDLE_DIR is sys._MEIPASS — the temp / onedir extraction root.  The
# split keeps user data outside _internal/ so upgrades just replace the
# bundle and the data dirs survive untouched.
if getattr(sys, 'frozen', False):
    BASE_DIR = os.path.dirname(os.path.abspath(sys.executable))
    BUNDLE_DIR = getattr(sys, '_MEIPASS', BASE_DIR)
else:
    BASE_DIR = os.path.dirname(os.path.abspath(__file__))
    BUNDLE_DIR = BASE_DIR

DB_PATH = os.environ.get('RETRODB_DB_PATH', os.path.join(BASE_DIR, "database", "roms.db"))
STATIC_PATH = os.path.join(BUNDLE_DIR, "static")
IMAGE_PATH = os.path.join(BASE_DIR, "static", "images")

# Path defaults (empty — set via Settings page, stored in data/settings.json)
ROM_PATH = ""
ESDE_GAMELISTS_PATH = ""
ESDE_DOWNLOADED_MEDIA_PATH = ""
RPCS3_TROPHY_PATH = ""

# =============================================================================
# API KEY DEFAULTS (empty — set via Settings page, stored in data/scraper_settings.json)
# =============================================================================

THEGAMESDB_API_KEY = ""
THEGAMESDB_PUBLIC_API_KEY = ""
IGDB_CLIENT_ID = ""
IGDB_CLIENT_SECRET = ""
RAWG_API_KEY = ""
RETROACHIEVEMENTS_USERNAME = ""
RETROACHIEVEMENTS_API_KEY = ""

# AI Metadata Scraper (Gemini, OpenAI, or Claude)
AI_METADATA_PROVIDER = ""     # "gemini", "openai", or "claude"
AI_GEMINI_API_KEY = ""
AI_OPENAI_API_KEY = ""
AI_CLAUDE_API_KEY = ""

# =============================================================================
# SCRAPER TOGGLES
# =============================================================================
# Enable or disable individual scrapers
# Set to False to disable a scraper (useful if API is down or causing issues)

SCRAPER_ESDE_ENABLED = True       # ES-DE local gamelist.xml
SCRAPER_TGDB_ENABLED = True       # TheGamesDB
SCRAPER_IGDB_ENABLED = True       # IGDB
SCRAPER_RAWG_ENABLED = True       # RAWG.io

# =============================================================================
# SERVER CONFIGURATION
# =============================================================================

# Flask server settings (overridable via RETRODB_HOST, RETRODB_PORT, RETRODB_DEBUG)
SERVER_HOST = os.environ.get('RETRODB_HOST', "0.0.0.0")
SERVER_PORT = int(os.environ.get('RETRODB_PORT', "5000"))
DEBUG_MODE = os.environ.get('RETRODB_DEBUG', "false").lower() in ('true', '1', 'yes')

# Slow-query threshold (ms).  When > 0, services.database logs a WARNING for
# any query/execute call that exceeds the threshold, including the SQL text
# and argument count.  0 (default) disables the check entirely.
# Override via RETRODB_SLOW_QUERY_MS=100 to enable in dev.
try:
    SLOW_QUERY_MS = int(os.environ.get('RETRODB_SLOW_QUERY_MS', '0'))
except ValueError:
    SLOW_QUERY_MS = 0

# Slow-request threshold (ms).  When > 0, app.py logs a WARNING for any HTTP
# request whose handler runs longer than the threshold, including method,
# path, and status code.  Pairs with SLOW_QUERY_MS — slow-query catches the
# DB layer; slow-request catches the whole handler (template render, scraper
# fan-out, etc.).  Default 500 ms matches "user-perceptible latency"; set to
# 0 to disable.  Override via RETRODB_SLOW_REQUEST_MS.
try:
    SLOW_REQUEST_MS = int(os.environ.get('RETRODB_SLOW_REQUEST_MS', '500'))
except ValueError:
    SLOW_REQUEST_MS = 500

# =============================================================================
# APPLICATION SETTINGS
# =============================================================================

# Application metadata
APP_NAME = "RetroDB"
APP_VERSION = "3.6.28"
APP_LAST_UPDATE = "2026-06-04"
APP_DESCRIPTION = "Retro Gaming ROM Library Manager"

# Supported image extensions for boxart/screenshots
SUPPORTED_IMAGE_EXTENSIONS = ['.jpg', '.jpeg', '.png', '.gif', '.webp']

# =============================================================================
# IMAGE STANDARDIZATION (Real-ESRGAN upscaling + Lanczos downscaling)
# =============================================================================

IMAGE_TARGET_HEIGHT = 1080                # Target height for boxart, screenshots, boxart_3d
IMAGE_TARGET_LONGEST_EDGE = 1280          # Target longest edge for controllers (irregular shapes)
IMAGE_UPSCALE_THRESHOLD = 0.80            # Upscale if below 80% of target
IMAGE_DOWNSCALE_THRESHOLD = 1.20          # Downscale if above 120% of target
REALESRGAN_MODEL_NAME = 'RealESRGAN_x4plus'
REALESRGAN_TILE_SIZE = 256
REALESRGAN_MODEL_URL = 'https://huggingface.co/Xenova/realesrgan-x4plus/resolve/main/model.onnx'
IMAGE_SKIP_TYPES = ['fanart']             # Image types to skip standardization

# On-ingest image format.  'webp' (default) saves 25-35% vs JPEG at equivalent
# visual quality and is supported by ~97% of browsers in 2026. Set to 'jpeg'
# to preserve the legacy pipeline. Videos, manuals, and GIFs are always kept
# in their original format.  Override with RETRODB_IMAGE_FORMAT=jpeg.
IMAGE_FORMAT = os.environ.get('RETRODB_IMAGE_FORMAT', 'webp').lower()
if IMAGE_FORMAT not in ('webp', 'jpeg'):
    IMAGE_FORMAT = 'webp'

# Maximum HTTP request body size, in bytes. Werkzeug enforces this at the
# WSGI layer before any handler runs — a multipart edit-modal POST with
# boxart + boxart_3d + several screenshots can easily exceed the old 16 MB
# default. Per-file caps in services.game_media_service still apply.
# Override via RETRODB_MAX_UPLOAD_MB.
try:
    _max_upload_mb = int(os.environ.get('RETRODB_MAX_UPLOAD_MB', '64'))
except ValueError:
    _max_upload_mb = 64
MAX_UPLOAD_BYTES = _max_upload_mb * 1024 * 1024

# Pass 25 — per-operation size and response caps.  Werkzeug's
# MAX_CONTENT_LENGTH backstops any HTTP body, but some code paths (scraper
# streaming downloads, SS API JSON, PDF parsing) pre-size their reads from
# the remote response — not the request body — so they need their own caps.
MAX_VIDEO_SIZE = 50 * 1024 * 1024              # 25.6 — per-upload video cap
MAX_MEDIA_DOWNLOAD_BYTES = 50 * 1024 * 1024    # 25.7 — scraper streaming download cap
MAX_API_RESPONSE_BYTES = 10 * 1024 * 1024      # 25.7 — scraper JSON response cap
MUSEUM_UPLOAD_MAX_BYTES = 10 * 1024 * 1024     # 25.4 — museum controller-image cap
CLZ_PDF_MAX_PAGES = 500                        # 25.5 — CLZ PDF page-count ceiling
MAX_LIST_ROWS = 500                            # 25.8 — list-endpoint row cap
# Pass 45.6 — Pillow decompression-bomb cap. A maliciously-crafted PNG can
# decode to gigabytes of pixel data even if the file itself is small. Caps
# Image.MAX_IMAGE_PIXELS at module-import time in services/image_utils.py
# and services/game_media_service.py. 64 megapixels (~8K × 8K) is well above
# any legitimate game cover or screenshot.
IMAGE_MAX_PIXELS = 64_000_000                  # 45.6 — Pillow decompression-bomb cap

# Maximum results to show in search
MAX_SEARCH_RESULTS = 10

# Maximum number of database backups to retain. Older backups beyond this
# count are pruned after each new backup. `pre_restore_*` backups created
# automatically before a restore are exempt and never pruned.
# Override via RETRODB_MAX_BACKUPS.
try:
    MAX_BACKUPS = int(os.environ.get('RETRODB_MAX_BACKUPS', '30'))
except ValueError:
    MAX_BACKUPS = 30

# How many days of completed/failed/dismissed/cancelled job_queue rows to
# keep. Active states (running, queued, interrupted) are never swept.
# Set to 0 or negative to disable the sweep. Override via
# RETRODB_JOB_HISTORY_RETENTION_DAYS.
try:
    JOB_HISTORY_RETENTION_DAYS = int(os.environ.get('RETRODB_JOB_HISTORY_RETENTION_DAYS', '30'))
except ValueError:
    JOB_HISTORY_RETENTION_DAYS = 30

